"""Settings tab — editor for sources.md and git checkpoint controls."""

from __future__ import annotations

import logging
import subprocess
import threading
import tkinter as tk
from typing import Any

from personal_assistant.models import NotifyTabCallback
from personal_assistant.config import (
    ASSISTANT_DIR,
    BG_INPUT,
    BG_WINDOW,
    COLOR_BUTTON,
    COLOR_BUTTON_ACTIVE,
    FG_DIM,
    FG_TEXT,
    FONT_NAME_BODY,
    FONT_NAME_INPUT,
    PAD,
)

logger = logging.getLogger(__name__)

SOURCES_PATH = ASSISTANT_DIR / "sources.md"


class SettingsTab:
    """Settings tab — edit sources.md and checkpoint via git."""

    def __init__(
        self,
        parent: tk.Frame,
        root: tk.Tk,
        *,
        console_log: Any = None,
        notify_tab_persistent: NotifyTabCallback | None = None,
        clear_persistent_bell: NotifyTabCallback | None = None,
    ) -> None:
        self._parent = parent
        self._root = root
        self._console_log = console_log
        self._notify_tab_persistent = notify_tab_persistent
        self._clear_persistent_bell = clear_persistent_bell
        self._last_saved = ""
        self._dirty = False
        self._build()

    def _build(self) -> None:
        # --- Sources editor section ---
        header = tk.Frame(self._parent, bg=BG_WINDOW)
        header.pack(fill=tk.X, padx=PAD, pady=(PAD, 0))

        tk.Label(
            header,
            text="sources.md",
            bg=BG_WINDOW,
            fg=FG_TEXT,
            font=FONT_NAME_BODY,
        ).pack(side=tk.LEFT)

        self._status_var = tk.StringVar(value="")
        tk.Label(
            header,
            textvariable=self._status_var,
            bg=BG_WINDOW,
            fg=FG_DIM,
            font=FONT_NAME_BODY,
        ).pack(side=tk.LEFT, padx=(PAD, 0))

        tk.Button(
            header,
            text="Save",
            command=self._save,
            bg=COLOR_BUTTON,
            fg=FG_TEXT,
            font=FONT_NAME_BODY,
            relief=tk.FLAT,
            activebackground=COLOR_BUTTON_ACTIVE,
            cursor="hand2",
            padx=8,
        ).pack(side=tk.RIGHT)

        # Text editor
        editor_frame = tk.Frame(self._parent, bg=BG_WINDOW)
        editor_frame.pack(fill=tk.BOTH, expand=True, padx=PAD, pady=PAD)

        self._editor = tk.Text(
            editor_frame,
            bg=BG_INPUT,
            fg=FG_TEXT,
            font=FONT_NAME_INPUT,
            wrap=tk.WORD,
            padx=PAD,
            pady=PAD,
            insertbackground=FG_TEXT,
            highlightthickness=0,
            borderwidth=0,
            undo=True,
        )
        scroll = tk.Scrollbar(editor_frame, command=self._editor.yview)
        scroll.pack(side=tk.RIGHT, fill=tk.Y)
        self._editor.configure(yscrollcommand=scroll.set)
        self._editor.pack(fill=tk.BOTH, expand=True)

        self._editor.bind("<<Modified>>", self._on_modified)
        self._editor.bind("<Control-s>", self._on_ctrl_s)

        self._load()

        # --- Git checkpoint section ---
        checkpoint_frame = tk.Frame(self._parent, bg=BG_WINDOW)
        checkpoint_frame.pack(fill=tk.X, padx=PAD, pady=(0, PAD))

        tk.Label(
            checkpoint_frame,
            text="Git Checkpoint",
            bg=BG_WINDOW,
            fg=FG_TEXT,
            font=FONT_NAME_BODY,
        ).pack(side=tk.LEFT)

        self._checkpoint_status_var = tk.StringVar(value="")
        tk.Label(
            checkpoint_frame,
            textvariable=self._checkpoint_status_var,
            bg=BG_WINDOW,
            fg=FG_DIM,
            font=FONT_NAME_BODY,
        ).pack(side=tk.LEFT, padx=(PAD, 0))

        tk.Button(
            checkpoint_frame,
            text="Checkpoint",
            command=self._checkpoint,
            bg=COLOR_BUTTON,
            fg=FG_TEXT,
            font=FONT_NAME_BODY,
            relief=tk.FLAT,
            activebackground=COLOR_BUTTON_ACTIVE,
            cursor="hand2",
            padx=8,
        ).pack(side=tk.RIGHT)

        self._commit_msg = tk.Entry(
            checkpoint_frame,
            bg=BG_INPUT,
            fg=FG_TEXT,
            font=FONT_NAME_INPUT,
            insertbackground=FG_TEXT,
            highlightthickness=0,
            borderwidth=1,
        )
        self._commit_msg.insert(0, "checkpoint")
        self._commit_msg.pack(side=tk.RIGHT, padx=(PAD, PAD), fill=tk.X, expand=True)

    def _load(self) -> None:
        """Load sources.md into the editor."""
        try:
            content = SOURCES_PATH.read_text(encoding="utf-8")
        except FileNotFoundError:
            content = ""
            self._status_var.set("(file not found)")
        self._editor.delete("1.0", tk.END)
        self._editor.insert("1.0", content)
        self._last_saved = content
        self._dirty = False
        self._editor.edit_modified(False)

    def _save(self) -> None:
        """Write editor content back to sources.md."""
        content = self._editor.get("1.0", f"{tk.END}-1c")
        try:
            SOURCES_PATH.parent.mkdir(parents=True, exist_ok=True)
            SOURCES_PATH.write_text(content, encoding="utf-8")
            self._last_saved = content
            self._dirty = False
            self._status_var.set("Saved")
            self._editor.edit_modified(False)
            if self._clear_persistent_bell:
                self._clear_persistent_bell("\u2699")
        except OSError as exc:
            self._status_var.set(f"Error: {exc}")

    def _on_ctrl_s(self, _event: Any) -> str:
        """Handle Ctrl+S — save and suppress default binding."""
        self._save()
        return "break"

    def _on_modified(self, _event: Any) -> None:
        """Track dirty state when text changes."""
        if not self._editor.edit_modified():
            return
        content = self._editor.get("1.0", f"{tk.END}-1c")
        self._dirty = content != self._last_saved
        if self._dirty:
            self._status_var.set("(unsaved changes)")
            if self._notify_tab_persistent:
                self._notify_tab_persistent("\u2699")
        else:
            self._status_var.set("")
            if self._clear_persistent_bell:
                self._clear_persistent_bell("\u2699")
        self._editor.edit_modified(False)

    def _checkpoint(self) -> None:
        """Run git add/commit/push in the PA directory."""
        msg = self._commit_msg.get().strip() or "checkpoint"
        self._checkpoint_status_var.set("Running...")

        def _run() -> None:
            try:
                result = subprocess.run(
                    ["git", "add", "."],
                    cwd=str(ASSISTANT_DIR),
                    capture_output=True,
                    text=True,
                    timeout=30,
                )
                if result.returncode != 0:
                    self._root.after(
                        0,
                        self._checkpoint_done,
                        f"add failed: {result.stderr.strip()}",
                        True,
                    )
                    return

                result = subprocess.run(
                    ["git", "commit", "-m", msg],
                    cwd=str(ASSISTANT_DIR),
                    capture_output=True,
                    text=True,
                    timeout=30,
                )
                if result.returncode != 0:
                    stderr = result.stderr.strip()
                    stdout = result.stdout.strip()
                    if "nothing to commit" in stdout or "nothing to commit" in stderr:
                        self._root.after(
                            0, self._checkpoint_done, "Nothing to commit", False
                        )
                    else:
                        self._root.after(
                            0,
                            self._checkpoint_done,
                            f"commit failed: {stderr or stdout}",
                            True,
                        )
                    return

                result = subprocess.run(
                    ["git", "push"],
                    cwd=str(ASSISTANT_DIR),
                    capture_output=True,
                    text=True,
                    timeout=60,
                )
                if result.returncode != 0:
                    self._root.after(
                        0,
                        self._checkpoint_done,
                        f"push failed: {result.stderr.strip()}",
                        True,
                    )
                    return

                self._root.after(0, self._checkpoint_done, "Checkpoint complete", False)

            except subprocess.TimeoutExpired:
                self._root.after(0, self._checkpoint_done, "Timed out", True)
            except OSError as exc:
                self._root.after(0, self._checkpoint_done, str(exc), True)

        threading.Thread(target=_run, daemon=True).start()

    def _checkpoint_done(self, message: str, is_error: bool) -> None:
        """Update checkpoint status on the main thread."""
        self._checkpoint_status_var.set(message)
        if self._console_log:
            tag = "error" if is_error else "success"
            self._console_log(f"Git checkpoint: {message}", tag, "", "")

    def on_destroy(self) -> None:
        """Cleanup — nothing to tear down currently."""
